def regex_match(s: str, p: str) -> bool:
    i = 0
    j = 0
    while i < len(s) and j < len(p):
        if p[j] == '.' or p[j] == s[i]:
            i += 1
            j += 1
        elif p[j] == '*':
            if j + 1 < len(p) and (p[j + 1] == '.' or p[j + 1] == s[i]):
                j += 2
                i += 1
            else:
                j += 1
        else:
            return False
    return j == len(p)
