    if k > n:
        return []
    result = []
    queue = []
    for i in range(k):
        while queue and nums[i] >= nums[queue[-1]]:
            queue.pop()
        queue.append(i)
    result.append(nums[queue[0]])
    for i in range(k, n):
        while queue and queue[0] <= i - k:
            queue.pop(0)
        while queue and nums[i] >= nums[queue[-1]]:
            queue.pop()
        queue.append(i)
        result.append(nums[queue[0]])
