def caesar_shift(s: str, k: int) -> str:
    result = []
    for char in s:
        if char.isalpha():
            start = ord('a') if char.islower() else ord('A')
            shifted_char = chr((ord(char) - start + k) % 26 + start)
        else:
            shifted_char = char
        result.append(shifted_char)
    return ''.join(result)
