def n_queens(n: int) -> int:
    def is_safe(board, row, col):
        for i in range(row):
            if board[i][col] == 1:
                return False
        for i, j in zip(range(row), range(col, -1, -1)):
            if board[i][j] == 1:
                return False
        for i, j in zip(range(row), range(col, n)):
            if board[i][j] == 1:
                return False
        return True

    def backtrack(row):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if is_safe(board, row, col):
                board[row][col] = 1
                count += backtrack(row + 1)
                board[row][col] = 0
        return count

    board = [[0 for _ in range(n)] for _ in range(n)]
    return backtrack(0)

```

