def evaluate(expr: str) -> int:
    expr = expr.replace(" ", "")
    if expr.isdigit():
        return int(expr)

    stack = []
    ops = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
        "/": lambda a, b: int(a / b)
    }

    for char in expr:
        if char.isdigit():
            stack.append(int(char))
        elif char in ops:
            operand2 = stack.pop()
            operand1 = stack.pop()
            result = ops[char](operand1, operand2)
            stack.append(result)
        elif char == "(":
            stack.append(char)
        elif char == ")":
            while stack and stack[-1] != "(":
                operand2 = stack.pop()
                operand1 = stack.pop()
                op = stack.pop()
                result = ops[op](operand1, operand2)
                stack.append(result)
            stack.pop()  # Discard the "("

    return stack[0] 
