def evaluate(expr: str) -> int:
    expr = expr.replace(" ", "")
    if expr.isdigit():
        return int(expr)
    stack = []
    operators = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: int(a / b),
    }
    for char in expr:
        if char in operators:
            operand2 = stack.pop()
            operand1 = stack.pop()
            result = operators[char](operand1, operand2)
            stack.append(result)
        elif char == '(':
            stack.append(char)
        elif char == ')':
            while stack and stack[-1] != '(':
                operand2 = stack.pop()
                operand1 = stack.pop()
                operator = stack.pop()
                result = operators[operator](operand1, operand2)
                stack.append(result)
            stack.pop()  # Discard the '('
        else:
            stack.append(int(char))
    return stack[0]
```

