def evaluate(expr: str) -> int:
    expr = expr.replace(" ", "")
    if expr.isdigit():
      return int(expr)

    def apply_operator(left, right, op):
      if op == '+':
        return left + right
      elif op == '-':
        return left - right
      elif op == '*':
        return left * right
      elif op == '/':
        return left // right

    stack = []
    for char in expr:
      if char.isdigit():
        stack.append(int(char))
      elif char in ('+', '-', '*', '/'):
        while stack and (stack[-1] in ('+', '-', '*', '/') or char == '*'):
          right = stack.pop()
          left = stack.pop()
          op = stack.pop()
          stack.append(apply_operator(left, right, op))
        stack.append(char)
      elif char == '(':
        stack.append(char)
      elif char == ')':
        while stack and stack[-1] != '(':
          right = stack.pop()
          left = stack.pop()
          op = stack.pop()
          stack.append(apply_operator(left, right, op))
        stack.pop()  

    while stack:
      right = stack.pop()
      left = stack.pop()
      op = stack.pop()
      stack.append(apply_operator(left, right, op))
    return stack[0]    
```

